<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {RefreshCw, Server, Cable, Database, Search, Radio, CheckCircle2, CircleAlert} from 'lucide-vue-next'
import {api} from '../api'
interface Service {system:string;base_url:string;status:string;duration_ms:number}
interface Call {timestamp:string;source:string;system:string;method:string;path:string;status:string;status_code:number;duration_ms:number;tool_name:string}
interface Tool {name:string;description:string;system:string;parameters:Record<string,unknown>;last_status:string|null;last_called_at:string|null}
interface Config {provider:string;model:string;base_url:string;api_key_configured:boolean;temperature:number;max_tokens:number;timeout:number}
const route=useRoute(), busy=ref(false),error=ref(''),services=ref<Service[]>([]),logs=ref<Call[]>([]),tools=ref<Tool[]>([]),config=ref<Config>(),search=ref(''),filter=ref(''),testing=ref(false),testMsg=ref(''),testOk=ref(false)
const page=computed(()=>route.name), systemNames:Record<string,string>={ERP:'企业资源计划',MES:'制造执行系统',AI:'AI Agent 服务'}
const visible=computed(()=>tools.value.filter(t=>(!filter.value || t.system===filter.value) && [t.name,t.description].join(' ').toLowerCase().includes(search.value.toLowerCase())))
const status=(s:string|null)=>s==='success'?'成功':s==='error'?'失败':s==='timeout'?'超时':'暂无调用'
const fmt=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—'
let generation=0
async function load(){const seq=++generation;busy.value=true;error.value='';try{if(page.value==='integrations'){
const [a,b]=await Promise.all([api.get('/system/integrations'),api.get('/system/call-logs',{params:{limit:50}})]);if(seq===generation){services.value=a.data.items;logs.value=b.data.items}}
else if(page.value==='tools'){const r=await api.get('/agent/tools');if(seq===generation)tools.value=r.data}
else {const r=await api.get('/system/model-config');if(seq===generation)config.value=r.data}}
catch{if(seq===generation)error.value='读取失败，请确认 AI 服务已启动后刷新。'}finally{if(seq===generation)busy.value=false}}
watch(page,()=>{search.value='';filter.value='';testMsg.value='';void load()},{immediate:true})
async function test(){testing.value=true;testMsg.value='';try{const r=await api.post('/system/model-test');testOk.value=r.data.supports_tool_calls;testMsg.value=`${r.data.model} 已返回原生工具调用，耗时 ${r.data.duration_ms} ms。`}catch(e:any){testOk.value=false;testMsg.value=e.response?.data?.detail||'模型连接失败，请检查本地网关配置。'}finally{testing.value=false}}
</script>
<template><div class="sys"><div class="sys-actions"><p>{{page==='integrations'?'服务连通性与最近业务请求':page==='tools'?'查看 Agent 可调用的只读工具、参数与执行状态':'查看当前模型配置并验证网关连通性'}}</p><el-button @click="load" :loading="busy"><RefreshCw :size="15"/>刷新</el-button></div>
<el-alert v-if="error" type="error" :title="error" :closable="false"/>
<div v-else class="sys-content" :class="{pending:busy}"><template v-if="page==='integrations'"><section class="services"><article v-for="s in services" :key="s.system"><div class="svc-top"><component :is="s.system==='ERP'?Database:s.system==='MES'?Cable:Server"/><el-tag :type="s.status==='ok'?'success':'danger'">{{s.status==='ok'?'健康':'异常'}}</el-tag></div><h2>{{s.system}}</h2><p>{{systemNames[s.system]}}</p><code>{{s.base_url}}</code><small>健康检查耗时 {{s.duration_ms}} ms</small></article></section><div class="sys-panel"><h2>最近调用记录</h2><el-table :data="logs" stripe empty-text="暂无调用记录"><el-table-column label="时间" min-width="155"><template #default="{row}">{{fmt(row.timestamp)}}</template></el-table-column><el-table-column prop="system" label="系统" width="70"/><el-table-column prop="path" label="请求路径" min-width="225"/><el-table-column prop="tool_name" label="工具" min-width="160"/><el-table-column label="状态" width="82"><template #default="{row}">{{status(row.status)}}</template></el-table-column><el-table-column prop="duration_ms" label="耗时 ms" width="85"/></el-table></div></template>
<template v-else-if="page==='tools'"><div class="sys-panel"><div class="sys-filter"><h2>工具目录 <small>{{visible.length}}</small></h2><el-input v-model="search" clearable placeholder="搜索工具名称或用途" :prefix-icon="Search"/><el-select v-model="filter" clearable placeholder="全部系统"><el-option v-for="s in [...new Set(tools.map(t=>t.system))]" :key="s" :value="s" :label="s"/></el-select></div><el-table :data="visible" row-key="name" empty-text="没有匹配的工具"><el-table-column type="expand"><template #default="{row}"><div class="schema"><b>参数结构</b><pre>{{JSON.stringify(row.parameters,null,2)}}</pre></div></template></el-table-column><el-table-column prop="name" label="工具名称" min-width="215"/><el-table-column prop="description" label="业务用途" min-width="200"/><el-table-column prop="system" label="系统" width="98"/><el-table-column label="最近调用" width="95"><template #default="{row}">{{status(row.last_status)}}</template></el-table-column><el-table-column label="调用时间" min-width="155"><template #default="{row}">{{fmt(row.last_called_at)}}</template></el-table-column></el-table></div></template>
<template v-else-if="config"><div class="sys-panel settings"><h2><Radio :size="20"/> 模型网关</h2><dl><template v-for="[k,v] in [['协议',config.provider],['模型',config.model],['接口地址',config.base_url],['API Key',config.api_key_configured?'已配置':'待配置'],['温度',config.temperature],['最大输出 token',config.max_tokens],['请求超时',config.timeout+' 秒']]" :key="k"><dt>{{k}}</dt><dd>{{v}}</dd></template></dl><p>修改本机 <code>backend/.env</code> 中的模型参数后，重新测试连接。</p><el-button type="primary" @click="test" :loading="testing">{{testing?'正在验证工具调用':'测试模型连接'}}</el-button><p v-if="testMsg" role="status"><component :is="testOk?CheckCircle2:CircleAlert" :size="16"/> {{testMsg}}</p></div></template></div></div></template>
<style scoped>.sys-actions,.svc-top,.sys-filter,.settings h2,.settings p:last-child{display:flex;align-items:center;gap:10px}.sys-actions,.svc-top{justify-content:space-between}.sys-actions{margin-bottom:16px}.sys-actions p,.services p,.settings p{color:#63758b;font-size:13px}.sys-actions p{margin:0}.sys-content{min-height:160px;transition:opacity .15s}.sys-content.pending{opacity:.55}.services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:20px}.services article,.sys-panel{background:#fff;border:1px solid #dce3ec;border-radius:10px;padding:20px}.services article>small{display:block;color:#586b82;margin-top:10px}.svc-top svg{color:#245dce}.sys h2{font-size:17px;margin:0 0 15px}.services h2{margin:16px 0 0;font-size:22px}.services p{margin:3px 0 12px}.sys code,.schema pre{word-break:break-all;font-size:12px}.sys-panel{min-width:0}.sys-filter{flex-wrap:wrap;margin-bottom:16px}.sys-filter h2{margin:0 auto 0 0}.sys-filter small{color:#64778c}.sys-filter .el-input{width:220px}.sys-filter .el-select{width:120px}.schema{padding:12px 24px;background:#f5f8fb}.schema pre{white-space:pre-wrap;color:#334c69}.settings{max-width:800px}.settings dl{display:grid;grid-template-columns:130px 1fr;font-size:14px}.settings dt,.settings dd{padding:12px 0;margin:0;border-bottom:1px solid #e8ecf1}.settings dt{color:#66788f}.sys :deep(.el-button svg){margin-right:5px}@media(max-width:780px){.services{grid-template-columns:1fr}.sys-panel{padding:12px}.sys-actions{align-items:flex-start}.settings dl{grid-template-columns:100px 1fr}.settings dd{overflow-wrap:anywhere}}</style>
